// The energy question on the Samn-Perelli fatigue scale (src/fatigue.js): the seven statements, how an answer is read,
// the low-day rule of the mind check-ins, the server's check and the technical view's buttons.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { FATIGUE_STEPS, FATIGUE_RULE, FATIGUE_SOURCE, fatigueStep, isLowEnergy, fatigueWords } from '../src/fatigue.js';
import { createMachine } from '../src/engine.js';
import { CELLS, CREW, SHIP, SOURCES } from '../src/config.js';
import { assess, LEVEL, RULES } from '../src/state-levels.js';
import { eventProblem } from '../src/security.js';

const NOW = new Date('2026-11-15T12:00:00Z');
const DAY = 24 * 3600 * 1000;

test('seven statements in the order of the scale, from fully alert to completely exhausted, with their source', () => {
  assert.deepEqual(FATIGUE_STEPS.map((s) => s.step), [1, 2, 3, 4, 5, 6, 7]);
  assert.equal(FATIGUE_STEPS[0].text, 'Fully alert, wide awake, extremely energetic');
  assert.equal(FATIGUE_STEPS[4].text, 'Moderately tired, let down');
  assert.equal(FATIGUE_STEPS[6].text, 'Completely exhausted, unable to function effectively');
  for (const s of FATIGUE_STEPS) assert.ok(s.text.startsWith(s.short), `${s.step}: the short form starts the statement`);
  assert.equal(FATIGUE_RULE.lowFrom, 5);
  assert.equal(FATIGUE_RULE.draft, true);
  assert.match(FATIGUE_SOURCE.url, /^https:\/\/caa\.co\.uk\//);
});

test('an answer is a whole step from 1 to 7; the old words "energetic" and "sluggish" read as 2 and 5', () => {
  for (const n of [1, 4, 7]) assert.equal(fatigueStep(n), n);
  assert.equal(fatigueStep('5'), 5);
  assert.equal(fatigueStep('energetic'), 2);
  assert.equal(fatigueStep('sluggish'), 5);
  for (const bad of [0, 8, 2.5, '', ' ', null, undefined, 'tired', {}, true, [5], '5.5', '0x5', '5e0']) assert.ok(Number.isNaN(fatigueStep(bad)), String(bad));
  assert.equal(isLowEnergy(4), false);
  assert.equal(isLowEnergy(5), true);
  assert.equal(isLowEnergy(7), true);
  assert.equal(isLowEnergy('sluggish'), true);
  assert.equal(isLowEnergy('energetic'), false);
  assert.equal(fatigueWords(5), '5 of 7: moderately tired');
  assert.equal(fatigueWords('sluggish'), 'sluggish (read as 5 of 7: moderately tired)');
});

test('the mind rule: energy at 5 or more on enough of the last days gives attention, at 4 it does not', () => {
  const person = CREW.find((p) => p.id === 'crew-1');
  const run = (step) => {
    const machine = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true } });
    for (let d = 0; d < RULES.badDaysForAttention; d += 1) {
      machine.receive({ source: 'attitude-report', indicator: 'attitude', value: step, person: person.id, time: new Date(NOW.getTime() - d * DAY - 3600 * 1000) });
    }
    return assess({ machine, person, cells: CELLS, mission: { launch: '2026-06-01T00:00:00Z', today: NOW.toISOString(), landing: '2026-12-10T00:00:00Z' }, now: NOW }).psyche;
  };
  const tired = run(5);
  assert.equal(tired.level, LEVEL.ATTENTION);
  assert.equal(tired.items[0].kind, 'mood');
  assert.equal(tired.items[0].days, RULES.badDaysForAttention);
  assert.equal(run(4).level, LEVEL.FINE);
});

test('the server takes a whole step from 1 to 7 and the two old words, and refuses anything else', () => {
  const at = new Date(NOW.getTime() - 3600 * 1000).toISOString();
  const ev = (value) => ({ v: 1, kind: 'reading', time: at, person: 'crew-1', state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true }, reading: { source: 'attitude-report', indicator: 'attitude', value } });
  for (const ok of [1, 5, 7, '6', 'sluggish', 'energetic']) assert.equal(eventProblem(ev(ok), { now: NOW }), null, String(ok));
  for (const bad of [0, 8, 2.5, '5.5', '0x5', '5e0', true, 'tired']) assert.notEqual(eventProblem(ev(bad), { now: NOW }), null, String(bad));
});

test('the energy cell names the scale and its source, and the technical view offers steps on the scale', () => {
  const cell = CELLS.find((c) => c.indicator === 'attitude');
  assert.deepEqual(cell.scale, { min: 1, max: 7 });
  assert.equal(cell.src, FATIGUE_SOURCE);
  assert.match(cell.normText, /Samn-Perelli/);
  assert.match(cell.normText, /5 or more/);
  const presets = SOURCES.find((s) => s.id === 'attitude-report').presets;
  assert.ok(presets.length >= 2);
  for (const p of presets) assert.ok(Number.isInteger(p.value) && p.value >= 1 && p.value <= 7, p.label);
});

test('an old answer saved before the scale is kept and read: the machine records "sluggish" as step 5 and counts it low', () => {
  const machine = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true } });
  const old = machine.receive({ source: 'attitude-report', indicator: 'attitude', value: 'sluggish', person: 'crew-1', time: new Date(NOW.getTime() - 3600 * 1000) });
  assert.notEqual(old.status, 'unknown');
  const list = machine.history('crew-1', 'attitude');
  assert.equal(list.length, 1);
  assert.equal(fatigueStep(list[0].value), 5);
  assert.equal(isLowEnergy(list[0].value), true);
  const odd = machine.receive({ source: 'attitude-report', indicator: 'attitude', value: 2.5, person: 'crew-1', time: NOW });
  assert.equal(machine.history('crew-1', 'attitude').length, 1, 'a value between steps is not kept');
  assert.ok(odd);
});
